    function renderServices(){const q=serviceSearch.value.trim().toLowerCase();const list=services.filter(s=>(serviceFilter==='all'||s.cat===serviceFilter)&&(`${s.title} ${s.summary} ${s.authority}`.toLowerCase().includes(q))).sort((a,b)=>{const ai=featuredServiceIds.indexOf(a.id),bi=featuredServiceIds.indexOf(b.id);return (ai<0?99:ai)-(bi<0?99:bi)});serviceGrid.innerHTML=list.map(s=>{const featured=featuredServiceIds.includes(s.id);return `<button class="service-card${featured?' featured':''}" type="button" data-service="${s.id}">${featured?'<span class="featured-badge">Featured</span>':''}${serviceVisuals[s.id]||''}<span class="service-number">${s.n} · ${esc(s.authority)}</span><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><span class="card-foot"><span>Tafseel dekhein</span><span aria-hidden="true">→</span></span></button>`}).join('');serviceEmpty.style.display=list.length?'none':'block'}
