    const docsChecklist=text=>String(text).split(/;\s*|\.\s+(?=[A-Z])/).map(x=>x.trim().replace(/\.$/, '')).filter(Boolean);
    const serviceDialog=document.getElementById('service-dialog');
    function openService(id){const s=services.find(x=>x.id===id);if(!s)return;document.getElementById('service-dialog-title').textContent=s.title;document.getElementById('service-dialog-body').innerHTML=`<p><strong>${esc(s.authority)}</strong></p><p>${esc(s.intro)}</p><h3>Kise chahiye</h3><p>${esc(s.who)}</p>${s.difference?`<h3>Foundation, NGO aur trust mein farq</h3><p>${esc(s.difference)}</p>`:''}<h3>Official procedure</h3><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Required Documents / Darkaar Documents</h3><ul class="doc-checklist">${docsChecklist(s.docs).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="fact"><strong>Fee aur waqt:</strong> ${esc(s.fee)}</div>${s.sources.length?`<h3>Official sources</h3><div class="source-list">${s.sources.map(x=>`<a href="${esc(x[1])}" target="_blank" rel="noopener noreferrer">${esc(x[0])} ↗</a>`).join('')}</div>`:''}<h3>3 asaan qadam</h3><div class="service-quick-process"><div><strong>1. Rabta</strong><span>Call ya WhatsApp par service batayein.</span></div><div><strong>2. Documents</strong><span>Required record ki checklist hasil karein.</span></div><div><strong>3. Completion</strong><span>Agreed scope ke mutabiq process complete karein.</span></div></div><h3>Aam sawalat</h3><p><strong>Kya pehli baat-cheet free hai?</strong><br>Initial scope aur required documents ki mukhtasar discussion free hai. Detailed review ya drafting ki fee pehle confirm ki jati hai.</p><p><strong>Kya Karachi ke bahar bhi assistance mil sakti hai?</strong><br>Federal aur online processes ke liye Pakistan bhar mein guidance available hai. Provincial requirements authority ke mutabiq confirm hoti hain.</p><div class="service-dialog-actions"><a class="primary" href="#contact" data-service-inquiry="${esc(s.title)}">Free initial discussion / quote</a><a class="secondary" href="https://wa.me/923112610683?text=${encodeURIComponent(`Assalam-o-Alaikum, mujhe ${s.title} ke bare mein maloomat aur quote chahiye.`)}" target="_blank" rel="noopener noreferrer">WhatsApp karein</a><a class="secondary" href="tel:+923112610683">Call 0311-2610683</a><a class="secondary" href="mailto:taqi6200@gmail.com">Email karein</a></div>`;openDialog(serviceDialog)}
    serviceGrid.addEventListener('click',e=>{const btn=e.target.closest('[data-service]');if(btn)openService(btn.dataset.service)});document.getElementById('high-value-grid').addEventListener('click',e=>{const btn=e.target.closest('[data-featured-service]');if(btn)openService(btn.dataset.featuredService)});

    serviceDialog.addEventListener('click',e=>{const link=e.target.closest('[data-service-inquiry]');if(!link)return;e.preventDefault();const title=link.dataset.serviceInquiry,matching=[...document.getElementById('contact-service').options].find(option=>title.toLowerCase().includes(option.text.toLowerCase().split(' / ')[0]));document.getElementById('contact-service').value=matching?matching.value:'Dusra masla';document.getElementById('contact-message').value=`Mujhe ${title} ke bare mein initial discussion aur quote chahiye.`;serviceDialog.close();document.getElementById('contact').scrollIntoView({behavior:'smooth'});});

    const PPC_CHAPTERS=[
      {id:'I',label:'Chapter I · Introduction',test:s=>{const n=parseInt(s,10);return n>=1&&n<=5}},
      {id:'II',label:'Chapter II · General Explanations',test:s=>{const n=parseInt(s,10);return n>=6&&n<=52}},
      {id:'III',label:'Chapter III · Punishments',test:s=>{const n=parseInt(s,10);return n>=53&&n<=75}},
      {id:'IV',label:'Chapter IV · General Exceptions',test:s=>{const n=parseInt(s,10);return n>=76&&n<=106}},
      {id:'V-A',label:'Chapter V-A · Criminal Conspiracy',test:s=>/^120[- ]?[A-Z]/i.test(s)},
      {id:'V',label:'Chapter V · Abetment',test:s=>{const n=parseInt(s,10);return n>=107&&n<=120}},
      {id:'VI',label:'Chapter VI · Offences Against the State',test:s=>{const n=parseInt(s,10);return n>=121&&n<=130}},
      {id:'VII',label:'Chapter VII · Armed Forces',test:s=>{const n=parseInt(s,10);return n>=131&&n<=140}},
      {id:'VIII',label:'Chapter VIII · Public Tranquillity',test:s=>{const n=parseInt(s,10);return n>=141&&n<=160}},
      {id:'IX-A',label:'Chapter IX-A · Elections',test:s=>/^171[- ]?[A-Z]/i.test(s)},
      {id:'IX',label:'Chapter IX · Public Servants',test:s=>{const n=parseInt(s,10);return n>=161&&n<=171}},
      {id:'X',label:'Chapter X · Lawful Authority of Public Servants',test:s=>{const n=parseInt(s,10);return n>=172&&n<=190}},
      {id:'XI',label:'Chapter XI · False Evidence & Public Justice',test:s=>{const n=parseInt(s,10);return n>=191&&n<=229}},
      {id:'XII',label:'Chapter XII · Coin & Government Stamps',test:s=>{const n=parseInt(s,10);return n>=230&&n<=263}},
      {id:'XIII',label:'Chapter XIII · Weights & Measures',test:s=>{const n=parseInt(s,10);return n>=264&&n<=267}},
      {id:'XIV',label:'Chapter XIV · Public Health, Safety & Morals',test:s=>{const n=parseInt(s,10);return n>=268&&n<=294}},
      {id:'XV',label:'Chapter XV · Religion',test:s=>{const n=parseInt(s,10);return n>=295&&n<=298}},
      {id:'XVI',label:'Chapter XVI · Human Body',test:s=>{const n=parseInt(s,10);return n>=299&&n<=377}},
      {id:'XVII',label:'Chapter XVII · Property',test:s=>{const n=parseInt(s,10);return n>=378&&n<=462}},
      {id:'XVIII',label:'Chapter XVIII · Documents & Trade Marks',test:s=>{const n=parseInt(s,10);return n>=463&&n<=489}},
      {id:'XIX',label:'Chapter XIX · Contracts of Service',test:s=>{const n=parseInt(s,10);return n>=490&&n<=492}},
      {id:'XX-A',label:'Chapter XX-A · Offences Against Women',test:s=>/^498[- ]?[A-Z]/i.test(s)},
      {id:'XX',label:'Chapter XX · Marriage',test:s=>{const n=parseInt(s,10);return n>=493&&n<=498}},
      {id:'XXI',label:'Chapter XXI · Defamation',test:s=>{const n=parseInt(s,10);return n>=499&&n<=502}},
      {id:'XXII',label:'Chapter XXII · Criminal Intimidation & Insult',test:s=>{const n=parseInt(s,10);return n>=503&&n<=510}},
      {id:'XXIII',label:'Chapter XXIII · Attempts',test:s=>parseInt(s,10)===511}
    ];
    const ppcGrid=document.getElementById('ppc-grid'),ppcSearch=document.getElementById('ppc-search'),ppcChapter=document.getElementById('ppc-chapter'),ppcEmpty=document.getElementById('ppc-empty'),ppcPrev=document.getElementById('ppc-prev'),ppcNext=document.getElementById('ppc-next'),ppcPageStatus=document.getElementById('ppc-page-status'),ppcDialog=document.getElementById('ppc-dialog');
    const ppcPerPage=12;let ppcSections=[],ppcPage=1,ppcByOrder=new Map();
    const ppcChapterFor=section=>PPC_CHAPTERS.find(chapter=>chapter.test(String(section)))||{id:'other',label:'Other provisions'};
    function ppcMatches(item){const q=ppcSearch.value.trim().toLowerCase().replace(/^section\s*/,'');const chapter=ppcChapterFor(item.section);const hay=`${item.section} ${item.section_label} ${item.title_en} ${(item.urdu_headline||[]).join(' ')}`.toLowerCase();return(ppcChapter.value==='all'||chapter.id===ppcChapter.value)&&hay.includes(q)}
    function ppcSprite(item){if(item.visual_type==='legal-text')return 'ppc-text-visual';const slot=Number(item.sprite_position??(Number(item.order)-1)),chunk=String(Math.floor(slot/25)+1).padStart(2,'0'),pos=String(slot%25).padStart(2,'0');return `ppc-sprite ppc-sprite-${chunk} ppc-pos-${pos}`}
    function ppcVisual(item,full=false){return item.visual_type==='legal-text'?`<span class="ppc-text-visual" role="img" aria-label="Pakistan Penal Code ${esc(item.section_label)} legal text panel"><small>Pakistan Penal Code, 1860</small><strong>${esc(item.section_label)}</strong><em>${esc(item.title_en)}</em></span>`:`<span class="${ppcSprite(item)}" role="img" aria-label="${full?'Full ':''}Pakistan Penal Code ${esc(item.section_label)} visual card"></span>`}
    function renderPpc(){const list=ppcSections.filter(ppcMatches),pages=Math.max(1,Math.ceil(list.length/ppcPerPage));ppcPage=Math.min(ppcPage,pages);const start=(ppcPage-1)*ppcPerPage,shown=list.slice(start,start+ppcPerPage);ppcGrid.innerHTML=shown.map(item=>`<button class="ppc-card" type="button" data-ppc-order="${item.order}" aria-label="Open ${esc(item.section_label)}"><span class="ppc-card-media">${ppcVisual(item)}</span><span class="ppc-card-copy"><span class="ppc-section-badge">${esc(item.section_label)}</span><h4 dir="rtl" lang="ur">${esc((item.urdu_headline||[]).join(' '))}</h4><span class="ppc-card-title">${esc(item.title_en)}</span><span class="ppc-card-action">Full card &amp; caption dekhein →</span></span></button>`).join('');ppcEmpty.style.display=list.length?'none':'block';ppcEmpty.textContent='Is search ya chapter mein koi section nahi mila.';document.getElementById('ppc-pagination').style.display=list.length?'flex':'none';ppcPrev.disabled=ppcPage<=1;ppcNext.disabled=ppcPage>=pages;ppcPageStatus.textContent=list.length?`Sections ${start+1}-${Math.min(start+ppcPerPage,list.length)} of ${list.length}`:'';document.getElementById('ppc-visible-total').textContent=list.length}
    function openPpc(order){const item=ppcByOrder.get(Number(order));if(!item)return;const chapter=ppcChapterFor(item.section);document.getElementById('ppc-dialog-title').textContent=`${item.section_label} | ${item.title_en}`;const body=document.getElementById('ppc-dialog-body');body.innerHTML=`<div class="ppc-dialog-image">${ppcVisual(item,true)}</div><div class="ppc-dialog-meta"><span><strong>Legal order:</strong> ${item.order} of ${ppcSections.length}</span><span><strong>Chapter:</strong> ${esc(chapter.label)}</span></div><h3>Roman Urdu caption</h3>`;const caption=document.createElement('p');caption.className='ppc-caption';caption.textContent=item.caption;body.append(caption);const reference=document.createElement('div');reference.className='ppc-reference';const label=document.createElement('strong');label.textContent='Official reference';reference.append(label,document.createTextNode(item.reference||`Pakistan Penal Code, 1860, ${item.section_label}`));body.append(reference);openDialog(ppcDialog)}
    ppcGrid.addEventListener('click',event=>{const card=event.target.closest('[data-ppc-order]');if(card)openPpc(card.dataset.ppcOrder)});
    ppcSearch.addEventListener('input',()=>{ppcPage=1;renderPpc()});ppcChapter.addEventListener('change',()=>{ppcPage=1;renderPpc()});
    ppcPrev.addEventListener('click',()=>{if(ppcPage>1){ppcPage--;renderPpc();document.getElementById('ppc-series').scrollIntoView({behavior:'smooth'})}});ppcNext.addEventListener('click',()=>{ppcPage++;renderPpc();document.getElementById('ppc-series').scrollIntoView({behavior:'smooth'})});
    fetch('assets/data/ppc.json',{credentials:'omit',referrerPolicy:'no-referrer'}).then(response=>{if(!response.ok)throw new Error('PPC index unavailable');return response.json()}).then(data=>{ppcSections=data.slice().sort((a,b)=>Number(a.order)-Number(b.order));ppcByOrder=new Map(ppcSections.map(item=>[Number(item.order),item]));document.getElementById('ppc-total').textContent=ppcSections.length;document.getElementById('ppc-visible-total').textContent=ppcSections.length;const available=new Set(ppcSections.map(item=>ppcChapterFor(item.section).id));PPC_CHAPTERS.filter(chapter=>available.has(chapter.id)).forEach(chapter=>{const option=document.createElement('option');option.value=chapter.id;option.textContent=chapter.label;ppcChapter.append(option)});renderPpc();const requested=new URLSearchParams(location.search).get('ppc');if(requested){const found=ppcSections.find(item=>String(item.section).toUpperCase()===requested.toUpperCase());if(found)openPpc(found.order)}}).catch(()=>{ppcGrid.innerHTML='';ppcEmpty.textContent='Pakistan Penal Code series load nahi ho saki. Dobara page khol kar dekhein.';ppcEmpty.style.display='block';document.getElementById('ppc-pagination').style.display='none'});


    const slugify=value=>String(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
    const HUB_CITATIONS=[{"citation":"2026 SCMR 1","title":"AMBREEN AKRAM Versus ASAD ULLAH KHAN","court":"Supreme Court of Pakistan","date":"11 September 2025","bench":"Syed Mansoor Ali Shah and Aqeel Ahmed Abbasi, JJ","docket":"Civil Petition No. 1107-L of 2015 and Civil Appeal No. 247-L of 2017","subject":"family","holding":"A wife's right to maintenance flows unconditionally from a valid marriage; it is not contingent on consummation, rukhsati, or obedience. Rukhsati has no independent legal status, and conditioning maintenance on it violates constitutional dignity and equality.","verified":"2026-09-23","caption":"Can a wife be denied maintenance simply because rukhsati has not taken place?\nThe Supreme Court of Pakistan has given a clear, historic answer in Ambreen Akram vs Asad Ullah Khan.\n\nIn 2026 SCMR 1, the Court held that a wife's right to maintenance (nan-o-nafqa) attaches with the nikah itself. It is not conditional on rukhsati, consummation, or obedience. Rukhsati has no independent legal status under the law. The Court further held that if a husband refuses to pay maintenance, he must prove with clear and strong evidence that the wife has wholly and without cause brought the relationship to an end.\n\nFor law students, this judgment is a masterclass: the application of Articles 14, 25, and 35 of the Constitution to family law, gender-sensitive judicial language, and the institutional use of amicus curiae. For every citizen, the message is plain: no woman in Pakistan can be deprived of this fundamental right.\n\nThe Court also rejected the old \"maintenance for obedience\" concept of ihtibas, holding it against the Quranic vision of nikah built on affection and compassion.\n\nCase: Ambreen Akram vs Asad Ullah Khan, 2026 SCMR 1. Supreme Court of Pakistan, decided 11 September 2025. Bench: Syed Mansoor Ali Shah and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (Dawn report): https://www.dawn.com/news/1941362\n\nDo you think this judgment will actually bring change in our society?\n\n#PakistanLaw\n#FamilyLaw\n#SupremeCourtOfPakistan\n#KnowYourRights\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-1.png"},{"citation":"2026 SCMR 22","title":"Syed SAAD ALI and another Versus FEDERATION OF PAKISTAN through Secretary Ministry and others","court":"Supreme Court of Pakistan","date":"12 June 2025","bench":"Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ","docket":"C.P.L.As. Nos. 407-K and 449-K of 2021","subject":"service","holding":"Where the High Court decided the case without adjudicating the plea of vires of the challenged regulation, its judgment is sub-silentio and lacks authoritative weight; the Supreme Court set it aside and remanded for fresh adjudication. A decision reached without argument, without reference to the critical terms of the law and without citation of authority (sub silentio) has no binding precedential value. The vires of any law, rule or regulation can be tested on the touchstone of legislative competence and fundamental rights; there is a presumption in favour of constitutionality unless the enactment is ex facie violative of a constitutional provision. Words of a statute are first understood in their natural, ordinary or popular sense and construed according to their grammatical meaning, unless that leads to absurdity or the context or object of the statute suggests the contrary. \"Ultra vires\" means beyond the powers; \"intra vires\" means within the precincts of powers.","verified":"2026-09-23","caption":"If a court decides your case without even hearing your biggest legal question, is that judgment worth anything?\nThe Supreme Court says: no, it is worth nothing at all.\n\nIn Syed Saad Ali vs Federation of Pakistan, 2026 SCMR 22, contract employees of the Civil Aviation Authority challenged the vires of Regulation 21(1). The High Court decided the case without giving any finding on that central point. The Supreme Court held that such a judgment is \"sub-silentio\", a decision given without addressing the point at issue, and it carries no binding value. The judgment was set aside and the case sent back for rehearing.\n\nFor law students, this case cements three things: the sub-silentio doctrine, the test for vires (legislative competence and fundamental rights), and the presumption in favour of constitutionality. For every citizen, the lesson is practical: if your case is before a court and the judge has not addressed your main point, this judgment can help your lawyer argue the point again.\n\nCase: Syed Saad Ali vs Federation of Pakistan, 2026 SCMR 22. Supreme Court of Pakistan, decided 12 June 2025. Bench: Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (video explainer on the sub-silentio doctrine, 2026 SCMR 22): https://www.youtube.com/watch?v=hO0byllbl8g\n\nDid you know what sub-silentio meant before today?\n\n#PakistanLaw\n#KnowYourRights\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-22.png"},{"citation":"2026 SCMR 42","title":"AYAZ ALI and another Versus FEDERATION OF PAKISTAN and others","court":"Supreme Court of Pakistan","date":"17 July 2025","bench":"Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ","docket":"Civil Petition No. 1242-K of 2024","subject":"service","holding":"Good management entails wisdom, uprightness, empathy, fairness, non-discriminatory employment policies, equal opportunity as an employer, and a congenial working environment. A beneficial employment or recruitment policy circulated by management must be implemented equitably and even-handedly across the board, not by cherry-picking to deny its benefits to deserving contenders (Constitution Arts. 25, 27). The applications of the appellants (sons of deceased employees) under the deceased-employees quota, ignored despite the prevailing policy, must be decided by the authorities in accordance with the Bank's policy prevailing at the time.","verified":"2026-09-23","caption":"A bank made a policy for the children of its deceased employees, then quietly ignored some applications.\nThe Supreme Court reminded everyone that justice must be equal for all.\n\nIn Ayaz Ali vs Federation of Pakistan, 2026 SCMR 42, the National Bank had a quota policy for jobs for the children of deceased employees, but some applications were not decided under the policy in force at the time of application. The Supreme Court held that good management means wisdom, honesty, impartiality, and equal opportunity. A policy meant for everyone cannot be applied through cherry-picking. This is the demand of Articles 25 and 27 of the Constitution, equality before law and equality of opportunity in public employment.\n\nFor law students, note how Articles 25 and 27 apply to employment policies, and study the judicially recognized standards of \"good management\". For citizens, the takeaway is direct: if you are entitled under a government or bank quota policy and your application is being suppressed, this judgment supports your claim.\n\nCase: Ayaz Ali vs Federation of Pakistan, 2026 SCMR 42. Supreme Court of Pakistan, decided 17 July 2025. Bench: Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (APP report): https://www.app.com.pk/national/sc-orders-nbp-to-decide-jobs-for-children-of-deceased-employees-under-policy-in-force-at-time-of-application/\n\nIn your view, how much is merit actually followed in Pakistan?\n\n#PakistanLaw\n#EmploymentLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-42.png"},{"citation":"2026 SCMR 47","title":"IMRAN Versus The STATE","court":"Supreme Court of Pakistan","date":"26 September 2025","bench":"Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ","docket":"Jail Petition No. 479 of 2019","subject":"criminal","holding":"A single circumstance creating doubt in the prosecution case is sufficient to acquit the accused; the prosecution must prove its case beyond the shadow of doubt. Medical evidence is only supportive: it may confirm the injury, its nature and the kind of weapon used, but it cannot identify the assailant. Mere abscondence of an accused, by itself, is not sufficient to sustain conviction in the absence of other reliable evidence. When recovered empties and the weapon are deposited together at the Forensic Science Laboratory, the recovery and the positive FSL report lose evidentiary value. Witnesses whose presence at the spot is unexplained (neither their land nor the Arhat shown in the site plan) are chance witnesses whose evidence is not worthy of reliance.","verified":"2026-09-23","caption":"A 17-year-old boy was accused of murder. One doubt, and the whole case collapsed.\nThe Supreme Court once again reminded us: the benefit of doubt goes to the accused.\n\nIn Imran vs The State, 2026 SCMR 47, the prosecution's case rested on shaky ground. The motive was never proved. The witnesses were \"chance witnesses\" whose presence at the scene had no explanation. The pistol and the empties were deposited together at the FSL. And the Court held that mere abscondence is not enough for conviction. Even a single circumstance creating doubt is enough for acquittal.\n\nFor law students, this judgment is essential reading on the standard of benefit of doubt, the supportive (not conclusive) role of medical evidence, the law on chance witnesses, and the law on abscondence. For citizens, the reminder is powerful: an accusation by the police or the media is not a conviction. Every charge must be proved in court with evidence.\n\nCase: Imran vs The State, 2026 SCMR 47. Supreme Court of Pakistan, decided 26 September 2025. Bench: Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ.\n\nVerify here (official Prosecutor General Punjab case-law digest): https://pg.punjab.gov.pk/murder-cases\n\nDoes merely running away prove that someone is guilty?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-47.png"},{"citation":"2026 SCMR 60","title":"MUSHTAQ AHMED Versus The STATE","court":"Supreme Court of Pakistan","date":"18 June 2025","bench":"Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ","docket":"Jail Petition No. 853 of 2017","subject":"criminal","holding":"Unexplained delay in conducting the postmortem examination creates doubt in the prosecution case and damages it; it suggests the occurrence was unseen and time was consumed in procuring false eye-witnesses. Where eye-witnesses are all close relatives of the complainant, no independent residents were cited, and their conduct at the scene was unnatural, their presence at the time and place of occurrence is not proved. Material contradictions between witnesses on the motive (financial dispute versus marriage grudge) create doubt entitling the accused to acquittal. Where co-accused have been acquitted on the same set of evidence, the benefit of doubt must equally extend to the accused; evidence disbelieved against co-accused cannot sustain the accused's conviction without independent corroboration.","verified":"2026-09-23","caption":"A delayed postmortem turned an entire murder case upside down.\nThe Supreme Court treated the delay itself as evidence of a deeper problem.\n\nIn Mushtaq Ahmed vs The State, 2026 SCMR 60, the Court held that an unexplained delay in the postmortem suggests the incident was not witnessed at all, and that the time was used to prepare false witnesses. All the witnesses were relatives of the complainant. There were material contradictions on motive. And a conviction could not be maintained on the very evidence on which the co-accused had already been acquitted.\n\nFor law students, the learning points are clear: the effect of delay in postmortem, the distinction between interested and independent witnesses, material contradictions on motive, and the benefit of a co-accused's acquittal. For citizens, the principle is simple: failures in investigation ultimately go in favour of the accused, and that is what justice demands.\n\nCase: Mushtaq Ahmed vs The State, 2026 SCMR 60. Supreme Court of Pakistan, decided 18 June 2025. Bench: Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ.\n\nVerify here (official Prosecutor General Punjab case-law digest): https://pg.punjab.gov.pk/murder-cases\n\nIn your view, what is the bigger problem in our system: the witnesses or the investigation?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-60.png"},{"citation":"2026 SCMR 74","title":"FEDERATION OF PAKISTAN through Secretary, Ministry of Defence, Rawalpindi and others Versus ROOH UL AMIN","court":"Supreme Court of Pakistan","date":"13 October 2025","bench":"Syed Mansoor Ali Shah and Aqeel Ahmed Abbasi, JJ","docket":"Civil Petition No. 4430 of 2022","subject":"service","holding":"When adverse remarks that formed the sole basis of successive supersessions are expunged (upheld by the Supreme Court), they cease to exist ab initio and are deemed never to have been recorded; the supersessions resting on them collapse. Supersession orders are derivative and consequential; once their premise is extinguished, they are denuded of all legal effect, and non-challenge to them carries no independent significance. The law does not require a civil servant to separately challenge supersession orders whose substratum has been judicially erased; that would be a meaningless formality. When the foundation of an administrative order disappears, the superstructure built upon it cannot survive.","verified":"2026-09-23","caption":"You were repeatedly denied promotion because of adverse remarks in your record.\nBut what happens when those remarks themselves are wiped out?\n\nIn Federation of Pakistan vs Rooh Ul Amin, 2026 SCMR 74, the employee had been superseded again and again on the basis of adverse remarks. When the Tribunal expunged those remarks, and the Supreme Court upheld the expunction, the remarks were treated as if they had never existed. The supersessions built on those remarks collapsed with them. The Court said it plainly: when the foundation is gone, the structure built on it cannot stand.\n\nFor law students, note the ab initio effect of expunction, the principle governing derivative and consequential orders, and the careful distinction from Abdul Ghani Chaudhry (1998 SCMR 2544). For government employees, the message matters: a wrong ACR cannot destroy your career if the law sets it aside.\n\nCase: Federation of Pakistan vs Rooh Ul Amin, 2026 SCMR 74. Supreme Court of Pakistan, decided 13 October 2025. Bench: Syed Mansoor Ali Shah and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (Business Recorder report): https://www.brecorder.com/news/40388769/if-adverse-remarks-against-an-employee-set-aside-supersession-orders-cease-to-exist-sc\n\nIs the ACR system in your institution based on fairness?\n\n#PakistanLaw\n#ServiceLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-74.png"},{"citation":"2026 SCMR 77","title":"ALI ADNAN SHEIKHA Versus I.G. POLICE SINDH and others","court":"Supreme Court of Pakistan","date":"5 September 2025","bench":"Irfan Saadat Khan and Aqeel Ahmed Abbasi, JJ","docket":"Cr.P.L.A. No. 147-K of 2025","subject":"criminal","holding":"Information given to a public servant with a bona fide belief in its truth is \"not proved\", not \"false\", and cannot attract section 182 PPC unless its falsity is proved through judicial proceedings. Proceedings under section 182 PPC can only be initiated by the public servant before whom the false information was laid and which led to criminal proceedings found false through judicial process. Failure to prove allegations before the judicial forum does not make the information \"false\" so as to invoke penal provisions like section 182 PPC. In the absence of any judicial finding (by the lower appellate court, the investigating officer's opinion, or a judicial forum) that the information was false, section 182 PPC is not attracted.","verified":"2026-09-23","caption":"There is a difference between false information and information that is simply not proved.\nThat difference can save you from a brand new case.\n\nIn Ali Adnan Sheikha vs I.G. Police Sindh, 2026 SCMR 77, the Supreme Court clarified that information given in good faith is not \"false\" until its falsity is established through judicial proceedings. Section 182 of the Pakistan Penal Code can only be invoked by the public servant before whom the information was given. Mere failure to prove an accusation does not make the information false.\n\nFor law students, the key concepts are the scope of Section 182 PPC, the difference between \"false\" and \"not proved\", and the framework of Sections 173, 190, and 195 CrPC. For citizens, the protection is real: if you complained against someone and the complaint could not be proved, that does not mean a Section 182 case will be made against you.\n\nCase: Ali Adnan Sheikha vs I.G. Police Sindh, 2026 SCMR 77. Supreme Court of Pakistan, decided 5 September 2025. Bench: Irfan Saadat Khan and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (Dawn report): https://www.dawn.com/news/1942803\n\nDoes this law protect genuine complainants, or does it open the door to misuse?\n\n#PakistanLaw\n#CriminalLaw\n#KnowYourRights\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-77.png"},{"citation":"2026 SCMR 87","title":"IRSHAD KHAN Versus The STATE","court":"Supreme Court of Pakistan","date":"12 August 2025","bench":"Jamal Khan Mandokhail, Musarrat Hilali and Shakeel Ahmad, JJ","docket":"Cr.P.L.A. No. 219-P of 2023","subject":"criminal","holding":"Under the maxim \"communi observantia non est recedendum\", when the law prescribes a specific procedure it must be followed accordingly; any deviation renders the act questionable. In narcotics cases, a collective FSL analysis of all recovered parcels (without separate testing of each sample and individual reports) violates Supreme Court principles and destroys the credibility of the chemical examination. A collective forensic report raises serious doubts about the representative nature of the samples sent for chemical analysis. Where the recovered substance was sealed with a monogram (\"MN\") unrelated to any officer or witness and that fact remains unexplained, combined with procedural violations and absence of credible forensic evidence, the accused is entitled to acquittal.","verified":"2026-09-23","caption":"Twenty packets were tested together as one batch.\nThe Supreme Court said: the method itself was wrong.\n\nIn Irshad Khan vs The State, 2026 SCMR 87, a narcotics case, the FSL conducted a collective test of 20 packets of opium and 3 packets of chars, and never prepared a separate report for each packet. The seal affixed had no connection with any officer or witness. The Court applied the maxim \"communi observantia non est recedendum\", meaning where the law prescribes a method, that method must be followed. The collective report destroyed the credibility of the entire forensic evidence. The accused was acquitted.\n\nFor law students, this case teaches the FSL protocol in narcotics cases, the difference between collective and separate analysis, the importance of the seal and monogram, and the application of the communi observantia maxim. For citizens, the lesson is sobering: the price of a forensic error is paid by an innocent person with his freedom, which is why following procedure is the guarantee of justice.\n\nCase: Irshad Khan vs The State, 2026 SCMR 87. Supreme Court of Pakistan, decided 12 August 2025. Bench: Jamal Khan Mandokhail, Musarrat Hilali and Shakeel Ahmad, JJ.\n\nVerify here (full judgment text, legal blog): https://www.legalhelp1.com/2025/09/supreme-court-acquits-accused-in.html\n\nIs the standard of our forensic labs good enough for courtroom justice?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-87.png"},{"citation":"2026 SCMR 99","title":"BINYAMEEN Versus State","court":"Supreme Court of Pakistan","date":"28 August 2025","bench":"Syed Hasan Azhar Rizvi and Naeem Akhter Afghan, JJ","docket":"Criminal Petition No. 1055 of 2025","subject":"criminal","holding":"Where co-accused were granted bail and common intention remains to be determined at trial, the case falls within further inquiry under section 497(2) CrPC. An accused in judicial custody, no longer required for investigation, cannot be denied bail as punishment.","verified":"2026-09-23","caption":"Nine months passed without a single prosecution witness appearing, and still no bail?\nThe Supreme Court said: custody cannot become punishment.\n\nIn Binyameen vs The State, 2026 SCMR 99, five co-accused had already been granted bail by the High Court, and whether the accused shared their common intention was a matter to be decided at trial. The Supreme Court held this to be a case of \"further inquiry\" deserving bail under Section 497(2) CrPC. An accused in judicial custody who is no longer required for investigation cannot be kept in jail as a punishment. The allegations in the FIR will be proved at trial, not presumed beforehand.\n\nFor law students, the takeaways are the scope of further inquiry, the principle that vicarious liability and common intention are decided at the trial stage, and delay in trial as a ground for bail. For citizens, the rule is humane: arrest does not mean punishment, and even under-trial detention has its limits.\n\nCase: Binyameen vs The State, 2026 SCMR 99. Supreme Court of Pakistan, decided 28 August 2025. Bench: Syed Hasan Azhar Rizvi and Naeem Akhter Afghan, JJ.\n\nVerify here (Sindh High Court judgment quoting this precedent): https://caselaw.shc.gov.pk/caselaw/view-file/MzE2NjIzY2Ztcy1kYzgz\n\nIs the condition of under-trial prisoners in our system really justice?\n\n#PakistanLaw\n#CriminalLaw\n#BailLaw\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-99.png"},{"citation":"2026 SCMR 115","title":"Muhammad Daud and another Versus The State and another","court":"Supreme Court of Pakistan","date":"19 June 2025","bench":"Muhammad Hashim Khan Kakar, Aamer Farooq and Ali Baqar Najafi, JJ","docket":"Crl. P.L.As. Nos. 537 and 559 of 2025","subject":"criminal","holding":"At the bail stage each accused is attributed only the quantity of narcotics recovered from him individually (1 kg each), which carries a maximum of seven years under section 9(2)'s table and does not fall within the prohibitory clause of section 497 CrPC. Total collective recovery cannot be attributed to every accused absent confidence-inspiring material of conscious knowledge of the others' possession. Bail is the rule where the prohibitory clause does not apply, absent exceptional circumstances (repetition, absconsion); a bare apprehension that one accused was an Afghan national was not sufficient.","verified":"2026-09-23","caption":"Out of 3.2 kilograms of narcotics, only 1 kilogram was recovered from each accused.\nAnd that 1 kilogram is exactly what got them bail.\n\nIn Muhammad Daud vs The State, 2026 SCMR 115, the Supreme Court held that at the bail stage, each accused is answerable only for the quantity recovered from him. A collective recovery cannot be fastened on every accused unless each one's knowledge is proved. On 1 kilogram, the maximum sentence is 7 years, so the prohibitory clause of Section 497 CrPC was not attracted. Bail is the rule, and jail is the exception.\n\nFor law students, study the prohibitory clause of Section 497 CrPC, the quantity table in Section 9(c) of the CNSA, and the classical bail jurisprudence. For citizens, the point is practical: in narcotics cases the entire quantity is often dumped on all the accused together, and this judgment protects against that injustice.\n\nCase: Muhammad Daud vs The State, 2026 SCMR 115. Supreme Court of Pakistan, decided 19 June 2025. Bench: Muhammad Hashim Khan Kakar, Aamer Farooq and Ali Baqar Najafi, JJ.\n\nVerify here (official Prosecutor General Punjab narcotics case-law digest): https://pg.punjab.gov.pk/control_of%20_narcotic_substances\n\nIs making bail easier an act of justice or of leniency?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-115.png"},{"citation":"2026 SCMR 122","title":"UMER JAN Versus State","court":"Supreme Court of Pakistan","date":"19 August 2025","bench":"Muhammad Hashim Khan Kakar, Ishtiaq Ibrahim and Muhammad Ali Baqar Najafi, JJ","docket":"Jail Petition No. 554 of 2023 and Criminal Petition No. 127 of 2023","subject":"criminal","holding":"Conviction on the same set of evidence on which a co-accused was acquitted, with nothing distinguishing the petitioner's role, is against settled principles of evidence. Benefit of doubt: acquitted.","verified":"2026-09-23","caption":"One co-accused was acquitted on the same evidence. The other was convicted on that very evidence.\nThe Supreme Court said: this cannot happen.\n\nIn Umer Jan vs The State, 2026 SCMR 122, the petitioner was convicted on the same evidence on which his co-accused had been acquitted, and nothing was shown to distinguish his role. The FSL report revealed that 10 out of 15 empties were never fired from the Kalashnikov at all. The witness claimed direct firing from two automatic weapons, yet he remained completely unhurt. The Court granted acquittal on the benefit of doubt.\n\nFor law students, focus on appreciation of evidence, the role of the FSL, and the plausibility of a defence plea. For citizens, the principle is basic: two different verdicts on the same evidence is not justice.\n\nCase: Umer Jan vs The State, 2026 SCMR 122. Supreme Court of Pakistan, decided 19 August 2025. Bench: Muhammad Hashim Khan Kakar, Ishtiaq Ibrahim and Muhammad Ali Baqar Najafi, JJ.\n\nVerify here (law firm case-law digest citing the case): https://www.mandviwallaandzafar.com/wp-content/uploads/Case_Law_Updates_13_June_2026-copy.pdf\n\nSame evidence, two different verdicts, what kind of justice is that?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-122.png"},{"citation":"2026 SCMR 135","title":"ABDUL MATEEN MEHBOOB Versus State","court":"Supreme Court of Pakistan","date":"24 July 2025","bench":"Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ","docket":"Criminal Petition No. 104-K of 2025","subject":"criminal","holding":"Rule of consistency in bail: like cases must be treated alike. Recovery of a psychotropic substance without videography at the spot undermined the raid, and the accused's role required further proof. Bail allowed.","verified":"2026-09-23","caption":"A raid was conducted in Karachi, but no video of the spot was ever made.\nThe Supreme Court put the raid itself under question.\n\nIn Abdul Mateen Mehboob vs The State, 2026 SCMR 135, decided at the Karachi Registry, the recovery of a psychotropic substance (Rivotril/Clonazepam) was made without any videography or photography. The accused was neither the exporter, nor the shipper, nor the clearing agent, nor the financer, and he had no knowledge of the drugs at all. Since his role was the same as that of a co-accused already on bail, the rule of \"like cases should be treated alike\" applied, and bail was granted. The Court reminded everyone: the purpose of criminal law is to make the accused face trial, not to punish him before trial.\n\nFor law students, the concepts to master are the rule of consistency and parity in bail, further inquiry under Section 497(2) CrPC, and the importance of videography in raids. For the people of Karachi, the message is clear: procedural violations in raids will no longer survive in court.\n\nCase: Abdul Mateen Mehboob vs The State, 2026 SCMR 135. Supreme Court of Pakistan, decided 24 July 2025. Bench: Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ.\n\nVerify here (lawyer's case explainer video): https://www.youtube.com/watch?v=ACBmzQc7Faw\n\nIs a raid without video really trustworthy?\n\n#PakistanLaw\n#Karachi\n#BailLaw\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-135.png"},{"citation":"2026 SCMR 163","title":"QAISER Versus State","court":"Supreme Court of Pakistan","date":"22 September 2025","bench":"Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ","docket":"Jail Petition No. 940 of 2017","subject":"criminal","holding":"Blackening of wound margins can occur even from a long-range shot and does not by itself prove close-range firing. But where medical evidence fully supports trustworthy ocular testimony, the conviction stands.","verified":"2026-09-23","caption":"The edges of the wound were blackened. Does that prove the shot was fired from close range?\nThe Supreme Court said: not necessarily.\n\nIn Qaiser vs The State, 2026 SCMR 163, the Court clarified that blackening of wound margins can result from a distant shot as well, from a hot bullet touching the skin, or even through clothing. Blackening alone, without burning or tattooing, does not prove close-range firing. But in this case the conviction was maintained, because the medical evidence fully corroborated the witnesses, the witnesses were found reliable, and the accused was arrested at the scene soon after the incident.\n\nFor law students, this case defines the relationship between medical and ocular evidence, and how forensic findings must be interpreted. For citizens, it shows that forensic science now plays a decisive role in court decisions.\n\nCase: Qaiser vs The State, 2026 SCMR 163. Supreme Court of Pakistan, decided 22 September 2025. Bench: Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ.\n\nVerify here (official Prosecutor General Punjab case-law digest): https://pg.punjab.gov.pk/murder-cases\n\nHow important do you think forensic science is in court today?\n\n#PakistanLaw\n#CriminalLaw\n#Forensics\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-163.png"},{"citation":"2026 SCMR 171","title":"Mrs. TASNEEM ABBAS Versus ADDITIONAL DISTRICT JUDGE, LAHORE","court":"Supreme Court of Pakistan","date":"10 September 2025","bench":"Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ","docket":"C.A. No. 132-L of 2013","subject":"civil","holding":"Non-registration of tenancy with the rent registrar is a curable defect; the petitioner must get a chance to pay the fine, not face dismissal. A tenant's pending ownership suit is no ground to block eviction.","verified":"2026-09-23","caption":"You never registered your rent agreement with the rent registrar. Should you panic?\nThe Supreme Court says: no, this defect can be cured.\n\nIn Tasneem Abbas vs ADJ Lahore, 2026 SCMR 171, the Court held that non-registration of a tenancy with the rent registrar is a curable defect. The person seeking eviction must be given a chance to fix it on payment of a fine; the case cannot be thrown out directly. The Court also held that a tenant's claim of ownership through a declaration suit does not stop eviction unless a decree is obtained. And in a memorable line, the Court warned that comparing handwriting oneself, without an expert, is dangerous and unreliable.\n\nFor law students, note Sections 5 and 9 of the 2007 Ordinance, and Article 84 of the Qanun-e-Shahadat. For tenants and landlords in Karachi and Lahore alike, the advice is practical: write the agreement and get it registered, that is your real protection.\n\nCase: Tasneem Abbas vs ADJ Lahore, 2026 SCMR 171. Supreme Court of Pakistan, decided 10 September 2025. Bench: Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ.\n\nVerify here (legal blog reproducing the reported headnote): https://www.legalhelp1.com/2026/03/supreme-court-upholds-landlords-right.html\n\nTenant or landlord, what has your experience been like?\n\n#PakistanLaw\n#TenancyLaw\n#KnowYourRights\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-171.png"},{"citation":"2026 SCMR 182","title":"AZHAR IQBAL Versus State","court":"Supreme Court of Pakistan","date":"2 October 2025","bench":"Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ","docket":"Criminal Petitions Nos. 189, 92-L of 2020 and 1810-L of 2019","subject":"criminal","holding":"Withholding best evidence (CCTV footage) without justification draws an adverse inference. A single doubt acquits; dishonest improvements destroy a witness; motive alone cannot sustain conviction.","verified":"2026-09-23","caption":"Key evidence existed, but the prosecution never produced it in court.\nThe Supreme Court turned that silence into evidence.\n\nIn Azhar Iqbal vs The State, 2026 SCMR 182, the best available evidence was withheld. The Court held that withholding the best evidence without reason suggests it was not in the prosecution's favour, applying Article 129(g) of the Qanun-e-Shahadat. One doubt is enough for acquittal. A witness who dishonestly improves his own statement no longer remains reliable. And conviction cannot rest on motive alone when the eyewitness account, the recovery, and the medical evidence are all unreliable.\n\nFor law students, the doctrines to study are adverse inference, dishonest improvements by witnesses, and motive as a double-edged weapon. For citizens, the warning is welcome: where evidence exists, hiding it will not work anymore.\n\nCase: Azhar Iqbal vs The State, 2026 SCMR 182. Supreme Court of Pakistan, decided 2 October 2025. Bench: Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ.\n\nVerify here (Sindh High Court judgment citing this precedent on Article 129(g)): https://caselaw.shc.gov.pk/caselaw/view-file/MzEwODcxY2Ztcy1kYzgz\n\nShould the prosecution be allowed to hide key evidence?\n\n#PakistanLaw\n#CriminalLaw\n#KnowYourRights\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-182.png"},{"citation":"2026 SCMR 197","title":"JAHANGIR alias Jangu Versus State","court":"Supreme Court of Pakistan","date":"3 September 2025","bench":"Syed Hasan Azhar Rizvi and Malik Shahzad Ahmad Khan, JJ","docket":"Jail Petition No. 286 of 2020","subject":"criminal","holding":"Recovery witnesses withstood lengthy cross-examination, corroborating a case proved beyond doubt. Multiple life sentences for robbery with murder run concurrently. Appeal dismissed.","verified":"2026-09-23","caption":"Dacoity and murder: two life sentences. But will both punishments run together?\nThe Supreme Court said yes, they will run concurrently.\n\nIn Jahangir vs The State, 2026 SCMR 197, the witnesses of the recovered property, a motorcycle, a mobile phone, and an ID card, faced lengthy cross-examination and their statements did not break. The Court held that the case was proved beyond doubt. For murder during dacoity, under Sections 302(b) and 392 of the Pakistan Penal Code, both life sentences will run concurrently. The appeal was dismissed.\n\nFor law students, the learning lies in the corroborative value of recovery evidence, and the distinction between concurrent and consecutive sentences. For citizens, the message is firm: the law gives its harshest punishment for murder committed during dacoity.\n\nCase: Jahangir vs The State, 2026 SCMR 197. Supreme Court of Pakistan, decided 3 September 2025. Bench: Syed Hasan Azhar Rizvi and Malik Shahzad Ahmad Khan, JJ.\n\nVerify here (official digest, Prosecutor General Punjab): https://pg.punjab.gov.pk/murder-cases\n\nDoes harsh punishment stop crime, or does the system need to improve?\n\n#PakistanLaw\n#CriminalLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-197.png"},{"citation":"2026 SCMR 205","title":"MUHAMMAD KAMRAN Versus State","court":"Supreme Court of Pakistan","date":"16 May 2025","bench":"Muhammad Hashim Khan Kakar, Salahuddin Panhwar and Ishtiaq Ibrahim, JJ","docket":"Criminal Appeal No. 91 of 2024","subject":"criminal","holding":"A single shot at the chest, a vital organ, shows clear intent to kill. No one has the right to force another into marriage; killing over refusal is an affront to women's autonomy and dignity. Conviction upheld.","verified":"2026-09-23","caption":"She refused to marry him. So he shot her dead.\nThe Supreme Court called it what it is: an attack on a woman's honour and autonomy.\n\nIn Muhammad Kamran vs The State, 2026 SCMR 205, a single bullet on the chest, a vital organ, revealed a clear intention to kill. The Court said in unmistakable words: no one has the right to force anyone into marriage. Killing on refusal is an insult to a woman's autonomy and dignity, which the law protects. The motive was proved, the evidence was direct, and the conviction was maintained.\n\nFor law students, the focus is on the determination of intent through the vital organ rule, and the importance of motive. For citizens, and especially for girls, the message is empowering: refusal is your right, and the law stands with you.\n\nCase: Muhammad Kamran vs The State, 2026 SCMR 205. Supreme Court of Pakistan, decided 16 May 2025. Bench: Muhammad Hashim Khan Kakar, Salahuddin Panhwar and Ishtiaq Ibrahim, JJ.\n\nVerify here (EHLAM Magazine legal report): https://www.ehlammagazine.org/2025/08/the-supreme-court-speaks-her-life-her.html\n\nDoes our society truly accept a woman's refusal?\n\n#PakistanLaw\n#WomensRights\n#CriminalLaw\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-205.png"},{"citation":"2026 SCMR 208","title":"Mst. SHAISTA HUSSAIN Versus FARZANA NAHEED","court":"Supreme Court of Pakistan","date":"11 September 2025","bench":"Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ","docket":"C.P.L.A. No. 5516 of 2024","subject":"civil","holding":"Payment of rent is the sine qua non of the landlord-tenant relationship; the onus to prove it lies on the landlord. The Rent Tribunal has no jurisdiction where no such relationship exists.","verified":"2026-09-23","caption":"He kept possession of the property without paying any rent.\nThe Supreme Court said: then the landlord-tenant relationship does not even exist.\n\nIn Shaista Hussain vs Farzana Naheed, 2026 SCMR 208, the Court clarified that payment of rent is not mere custom; it is the sine qua non, the very foundation, of the landlord-tenant relationship. A person in possession who does not pay rent is not a tenant. The burden of proving this relationship lies on the landlord. And where the relationship itself does not exist, the Rent Tribunal has no jurisdiction either.\n\nFor law students, the key points are the onus of proof, the jurisdiction of the Rent Tribunal, and the 2009 Act. For the people of Karachi, this judgment will directly help in disputes over possession and rent.\n\nCase: Shaista Hussain vs Farzana Naheed, 2026 SCMR 208. Supreme Court of Pakistan, decided 11 September 2025. Bench: Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ.\n\nVerify here (video explainer on 2026 SCMR 208, landlord-tenant burden): https://www.youtube.com/watch?v=A_B6jEy24jE\n\nWhat is the best solution for rent disputes?\n\n#PakistanLaw\n#TenancyLaw\n#SupremeCourtOfPakistan\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-208.png"},{"citation":"2026 SCMR 217","title":"KHADIM HUSSAIN Versus State","court":"Supreme Court of Pakistan","date":"21 August 2025","bench":"Muhammad Hashim Khan Kakar, Ishtiaq Ibrahim and Ali Baqar Najafi, JJ","docket":"Criminal Petition No. 974 of 2025","subject":"criminal","holding":"Mere presence in the truck is not enough; Article 122 QSO does not apply without proof the accused knew of narcotics in secret cavities. Criminal liability is individual, not collective. Bail allowed.","verified":"2026-09-23","caption":"He was in the truck, but the drugs were hidden in secret compartments.\nIs mere presence alone a crime? The Supreme Court said no.\n\nIn Khadim Hussain vs The State, 2026 SCMR 217, 15 kilograms of narcotics, heroin, ice, opium, and chars, were hidden in the truck's secret compartments. The Court held that merely being in the truck is not enough unless conspiracy or abetment is proved. Article 122 of the Qanun-e-Shahadat, on exclusive knowledge, does not apply where knowledge itself is not proved. Criminal liability is individual, not collective. It was a case of further inquiry, and bail was granted.\n\nFor law students, the pillars here are actus reus plus mens rea, the scope of Article 122 QSO, and Section 497(2) CrPC. For citizens, the principle protects you: travelling with someone does not make you a criminal; knowledge and intention must be proved.\n\nCase: Khadim Hussain vs The State, 2026 SCMR 217. Supreme Court of Pakistan, decided 21 August 2025. Bench: Muhammad Hashim Khan Kakar, Ishtiaq Ibrahim and Ali Baqar Najafi, JJ.\n\nVerify here (official Sindh High Court caselaw site citing the judgment): https://caselaw.shc.gov.pk/caselaw/view-file/MzE3NzE5Y2Ztcy1kYzgz\n\nShould merely being with someone be treated as a crime?\n\n#PakistanLaw\n#NarcoticsLaw\n#BailLaw\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-217.png"},{"citation":"2026 SCMR 220","title":"SAHAD Versus Mst. AFSHEEN","court":"Supreme Court of Pakistan","date":"18 August 2025","bench":"Amin-ud-Din Khan and Syed Hasan Azhar Rizvi, JJ","docket":"Criminal Petition No. 1033 of 2025","subject":"criminal","holding":"Crime-scene empties not matching the weapon allegedly recovered from the accused render the recovery doubtful. A general narration attributing no specific role makes it a case of further inquiry. Bail allowed.","verified":"2026-09-23","caption":"The empties did not match the pistol recovered from the accused at all.\nOn what basis was the case standing then?\n\nIn Sahad vs Mst. Afsheen, 2026 SCMR 220, the empties found at the crime scene did not match the weapon recovered from the accused, which made the recovery doubtful. The eyewitness gave a general statement in which the accused had no specific role at all. The Supreme Court held this to be a case of further inquiry, and granted bail under Section 497(2) CrPC.\n\nFor law students, the study points are the effect of forensic mismatch, specific role attribution, and bail jurisprudence. For citizens, the rule is just: when the forensic evidence itself does not connect, no one can be kept in custody.\n\nCase: Sahad vs Mst. Afsheen, 2026 SCMR 220. Supreme Court of Pakistan, decided 18 August 2025. Bench: Amin-ud-Din Khan and Syed Hasan Azhar Rizvi, JJ.\n\nVerify here (official Sindh High Court caselaw site citing the judgment): https://caselaw.shc.gov.pk/caselaw/view-file/MzE5NDY3Y2Ztcy1kYzgz\n\nCan a case survive on a forensic mismatch?\n\n#PakistanLaw\n#CriminalLaw\n#BailLaw\n#TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-220.png"},{"citation":"2026 SCMR 138","title":"Abdul Majeed and others v. Haji Haq Nawaz","court":"Supreme Court of Pakistan","date":"27 October 2025","bench":"Shahid Waheed, Musarrat Hilali and Salahuddin Panhwar, JJ","docket":"C.P.L.A. No. 1010-L of 2014","subject":"civil","holding":"In pre-emption suits under section 13 of the Punjab Pre-emption Act, 1991, the pre-emptor must prove a valid and immediate Talb-i-Muwathibat; doubt concerning performance of the talbs benefits the vendee. Where the pre-emptor failed to prove it, the lower judgments were set aside and the suit dismissed.","verified":"2026-09-24","caption":"Kya shafa'at (pre-emption) ka dawa sirf talb-i-muwathibat sabit na hone par kharij ho sakta hai?\nSupreme Court ne wazeh kiya ke pre-emptor ko foran aur durust Talb-i-Muwathibat sabit karni hogi. Talb ki adayegi mein shak ka faida kharidar ko milega. Is bunyaad par neechli adalaton ke faislay kaladam qarar de kar dawa kharij kar diya gaya.\nCase: Abdul Majeed and others vs Haji Haq Nawaz, 2026 SCMR 138. Supreme Court of Pakistan, decided 27 October 2025. Bench: Shahid Waheed, Musarrat Hilali and Salahuddin Panhwar, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nProperty ke muqadmat mein shafa'at ke qanoon ka sahih istemal kitna zaroori hai?\n#PropertyLaw #SupremeCourtOfPakistan #PakistanLaw #KnowYourRights #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-138.png","reference":"2026 SCMR 138","src":"https://www.mandviwallaandzafar.com/wp-content/uploads/Case_Law_Updates_13_June_2026-copy.pdf"},{"citation":"2026 SCMR 141","title":"Messrs Allama Iqbal Open University v. Commissioner Inland Revenue, Withholding Tax Zone, Regional Tax Office, Islamabad","court":"Supreme Court of Pakistan","date":"9 October 2025","bench":"Munib Akhtar, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ","docket":"Civil Petition No. 4579 of 2023","subject":"tax","holding":"Section 11(4) of the Sales Tax Act, 1990 did not impose withholding-agent responsibility; section 11(4A), introduced in 2016, could not be applied retrospectively to the July 2012 to June 2013 tax periods. The High Court order was set aside.","verified":"2026-09-24","caption":"Kya tax ka qanoon pichhle saalon par bhi laagu ho sakta hai?\nSupreme Court ne 2026 SCMR 141 mein faisla diya ke Sales Tax Act ki section 11(4) mein withholding agent ki zimmedari thi hi nahi, aur 2016 mein aane wali section 11(4A) ko 2012-13 ke tax periods par laagu nahi kiya ja sakta. Qanoon peeche ki taraf (retrospective) laagu nahi hota.\nCase: Allama Iqbal Open University vs Commissioner Inland Revenue, 2026 SCMR 141. Supreme Court of Pakistan, decided 9 October 2025. Bench: Munib Akhtar, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya aap ke khayal mein tax notices mein aksar yahi ghalti hoti hai?\n#TaxLaw #SalesTax #SupremeCourtOfPakistan #PakistanLaw #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-141.png","reference":"2026 SCMR 141","src":"https://www.brecorder.com/news/40386858/sales-tax-on-supplies-services-sc-turns-down-ihc-verdict-against-aiou"},{"citation":"2026 SCMR 145","title":"Muhammad Rashid and another v. The State through DAG and another","court":"Supreme Court of Pakistan","date":"3 October 2025","bench":"Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ","docket":"Criminal Petitions Nos. 143 and 359 of 2023","subject":"criminal","holding":"The case was clouded by doubt, the Post Office Manual inquiry procedure was not properly followed, and the prosecution failed to prove guilt beyond reasonable doubt. Convictions and sentences under the Penal Code and the Prevention of Corruption Act were set aside and the accused acquitted.","verified":"2026-09-24","caption":"Jab prosecution apna case shak se pare (beyond reasonable doubt) sabit na kar sake to kya hota hai?\nSupreme Court ne 2026 SCMR 145 mein convictions kaladam kar ke mulziman ko bari kar diya, kyunke tehqeeqati tareeqakar durust nahi apnaya gaya tha aur case shak se bhara hua tha. Shak ka faida hamesha mulzim ko milta hai.\nCase: Muhammad Rashid and another vs The State, 2026 SCMR 145. Supreme Court of Pakistan, decided 3 October 2025. Bench: Athar Minallah, Irfan Saadat Khan and Malik Shahzad Ahmad Khan, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya corruption ke muqadmat mein tehqeeq ke mayar ko sakht karna chahiye?\n#CriminalLaw #SupremeCourtOfPakistan #PakistanLaw #KnowYourRights #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-145.png","reference":"2026 SCMR 145"},{"citation":"2026 SCMR 152","title":"Messrs Trio Industries (Pvt.) Limited v. Babu Sher and others","court":"Supreme Court of Pakistan","date":"2 June 2025","bench":"Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ","docket":"C.P.L.A. No. 451-K of 2023","subject":"service","holding":"An employer that submitted its factory-closure request to the wrong forum could not claim deemed approval after 15 days; the closure was unlawful. Since reinstatement was impracticable because the establishment had closed, compensation was proper. The Court also held that no person may benefit from their own wrong and ignorance of law is no excuse.","verified":"2026-09-24","caption":"Factory band karne se pehle employer ne darwaza hi ghalat khatkhataya, to kya closure qanooni ho sakti hai?\nSupreme Court ne 2026 SCMR 152 mein faisla diya ke ghalat forum mein darkhwast par 15 din ke baad deemed approval nahi banti. Bandish gair qanooni qarar pai. Establishment band ho chuki thi is liye mazdooron ko muaawza dena durust tha.\nCase: Trio Industries (Pvt.) Limited vs Babu Sher and others, 2026 SCMR 152. Supreme Court of Pakistan, decided 2 June 2025. Bench: Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nMazdooron ke haqooq ke tahaffuz ke liye aisi misalein kitni ahmiyat rakhti hain?\n#LabourLaw #EmploymentLaw #SupremeCourtOfPakistan #PakistanLaw #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-152.png","reference":"2026 SCMR 152","src":"https://osmanilaw.com/unlawful-closure-of-factory/"},{"citation":"2026 SCMR 190","title":"Sindh Irrigation and Drainage Authority v. Province of Sindh and another","court":"Supreme Court of Pakistan","date":"24 July 2025","bench":"Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ","docket":"Civil Appeal No. 80-K of 2022","subject":"civil","holding":"A decree issued by the High Court in its original jurisdiction attracted Article 151's 20-day limitation period, and the appeal was late even under Article 156's 90 days. Alleging the award was void did not justify condonation: every day's delay must be explained, and government bodies receive no preferential treatment in limitation.","verified":"2026-09-24","caption":"Kya sarkari idaray ke liye appeal ki muddat (limitation) mein koi riayat hoti hai?\nSupreme Court ne 2026 SCMR 190 mein wazeh kiya ke nahi. Waqt par appeal na hui to har din ki takheer ki wazahat deni hogi, aur sarkari idaray ko koi khaas riayat nahi milti. Adalaten limitation ka khayal khud bhi rakhen gi.\nCase: Sindh Irrigation and Drainage Authority vs Province of Sindh, 2026 SCMR 190. Supreme Court of Pakistan, decided 24 July 2025. Bench: Muhammad Ali Mazhar, Syed Hasan Azhar Rizvi and Aqeel Ahmed Abbasi, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya muddat guzarne par waqai insaaf ka darwaza band ho jata hai?\n#LimitationLaw #SupremeCourtOfPakistan #PakistanLaw #KnowYourRights #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-190.png","reference":"2026 SCMR 190","src":"https://www.mandviwallaandzafar.com/wp-content/uploads/Case_Law_Updates_13_June_2026-copy.pdf"},{"citation":"2026 SCMR 201","title":"Messrs WAK Limited, Multan Road, Lahore v. Collector Central Excise and Sales Tax Lahore (now Commissioner Inland Revenue LTU, Lahore) and others","court":"Supreme Court of Pakistan","date":"11 September 2025","bench":"Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ","docket":"Civil Appeals Nos. 634-636 of 2018","subject":"tax","holding":"The statutory periods for orders-in-original after show-cause notices are mandatory: the sales-tax order exceeded 120 days without valid extension and the excise order exceeded 45 days. Both orders were time-barred; the impugned judgments were set aside and the appeals allowed.","verified":"2026-09-24","caption":"Show-cause notice ke baad department ko order kitne waqt mein karna hota hai?\nChief Justice Yahya Afridi ki sarbarahi mein Supreme Court ne 2026 SCMR 201 mein faisla diya ke yeh muddaten lazmi hain. Sales tax order 120 din aur excise order 45 din se zyada late thay, is liye dono orders time-barred qarar pa kar kaladam ho gaye.\nCase: WAK Limited vs Commissioner Inland Revenue, 2026 SCMR 201. Supreme Court of Pakistan, decided 11 September 2025. Bench: Yahya Afridi, CJ, Muhammad Shafi Siddiqui and Miangul Hassan Aurangzeb, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya tax department ko waqt ki pabandi par qanoon mein aur sakhti honi chahiye?\n#TaxLaw #SalesTax #SupremeCourtOfPakistan #PakistanLaw #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-201.png","reference":"2026 SCMR 201"},{"citation":"2026 SCMR 278","title":"Province of Sindh through Chief Secretary Government of Sindh and others v. Raj Kumar Lohana and others","court":"Supreme Court of Pakistan","date":"3 September 2025","bench":"Muhammad Ali Mazhar, Athar Minallah and Salahuddin Panhwar, JJ","docket":"Civil Appeals Nos. 53-K to 58-K of 2024","subject":"service","holding":"Seniority is a valuable right and cannot be altered adversely without notice and due process under Article 10-A. For reinstated ASIs, original seniority stood restored and was to be reckoned from initial appointment, the Government having supplied no adequate justification otherwise. The Sindh Service Tribunal judgment was upheld and the Government's appeals dismissed.","verified":"2026-09-24","caption":"Kya mulazim ki seniority bina notice ke tabdeel ki ja sakti hai?\nSupreme Court ne 2026 SCMR 278 mein faisla diya ke seniority qeemti haq hai, ise bina notice aur due process ke nahi cheena ja sakta. Bahal hone wale ASIs ki seniority unki pehli taqruri se shumaar hogi. Sindh Service Tribunal ka faisla barqarar, hukoomat ki appealain kharij.\nCase: Province of Sindh vs Raj Kumar Lohana and others, 2026 SCMR 278. Supreme Court of Pakistan, decided 3 September 2025. Bench: Muhammad Ali Mazhar, Athar Minallah and Salahuddin Panhwar, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nSindh ke sarkari mulazmeen ke liye yeh faisla kitni khushkhabri hai?\n#ServiceLaw #SindhHighCourt #SupremeCourtOfPakistan #PakistanLaw #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-278.png","reference":"2026 SCMR 278"},{"citation":"2026 SCMR 494","title":"Shafqat Ali v. Mst. Zaib Un Nisa and others","court":"Supreme Court of Pakistan","date":"20 August 2025","bench":"Amin-ud-Din Khan and Syed Hasan Azhar Rizvi, JJ","docket":"Civil Petition No. 74 of 2025","subject":"family","holding":"Where a family-court decree afforded alternate modes of satisfying dower (seven tolas of gold or, in the alternative, Rs.100,000/-), the decree-holder retained the liberty to exercise her choice, and an executing court could direct payment of the current market value of gold ornaments if their return was not possible. The Court must give effect to the true intent underlying the decree and the contract from which it flew.","verified":"2026-09-24","caption":"Haq mehr mein saat tole sona ya aik lakh rupay, ikhtiyar kiska?\nSupreme Court ne 2026 SCMR 494 mein faisla diya ke jab decree mein do tareeqay diye gaye hon to chunao decree-holder (biwi) ka hoga. Agar sona wapas mumkin na ho to executing court sona ki maujooda market qeemat ada karne ka hukm de sakti hai.\nCase: Shafqat Ali vs Mst. Zaib Un Nisa and others, 2026 SCMR 494. Supreme Court of Pakistan, decided 20 August 2025. Bench: Amin-ud-Din Khan and Syed Hasan Azhar Rizvi, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nHaq mehr ke muqadmat mein aurton ko apne haq ka ilm kitna zaroori hai?\n#FamilyLaw #SupremeCourtOfPakistan #PakistanLaw #KnowYourRights #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-494.png","reference":"2026 SCMR 494","src":"https://www.supremecourt.gov.pk/downloads_judgements/c.p.742025.pdf"},{"citation":"2026 SCMR 576","title":"The Senior General Manager (Chief Executive Officer), Pakistan Railways, Railway Headquarter, Lahore and others v. Syed Qaiser Abbas","court":"Supreme Court of Pakistan","date":"18 November 2025","bench":"Ayesha A. Malik and Aqeel Ahmed Abbasi, JJ","docket":"Civil Petition No. 2761 of 2023","subject":"service","holding":"A major penalty of dismissal from service cannot be awarded without a regular inquiry or an opportunity of being heard; this violates natural justice. A regular inquiry is required for any major or minor penalty unless dispensed with for sufficient reasons disclosed in writing, and Article 10-A's fair-trial guarantee must be read into every statute. The Service Tribunal's conversion of dismissal into compulsory retirement was left undisturbed.","verified":"2026-09-24","caption":"Bina regular inquiry ke mulazim ko nokri se nikalna kya qanooni hai?\nSupreme Court ne 2026 SCMR 576 mein faisla diya ke sunwai aur regular inquiry ke baghair dismissal natural justice ki khilaf warzi hai. Fair trial (Article 10-A) ka usool har qanoon mein parha jayega. Service Tribunal ka dismissal ko compulsory retirement mein tabdeel karna barqarar raha.\nCase: Pakistan Railways vs Syed Qaiser Abbas, 2026 SCMR 576. Supreme Court of Pakistan, decided 18 November 2025. Bench: Ayesha A. Malik and Aqeel Ahmed Abbasi, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya sarkari mulazmeen ke khilaf disciplinary karwai mein insaaf ka taqaza poora hota hai?\n#ServiceLaw #SupremeCourtOfPakistan #PakistanLaw #KnowYourRights #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-576.png","reference":"2026 SCMR 576"},{"citation":"2026 SCMR 692","title":"Muhammad Ali Wassan v. The Prime Minister of Pakistan and another","court":"Supreme Court of Pakistan","date":"4 June 2025","bench":"Muhammad Shafi Siddiqui and Salahuddin Panhwar, JJ","docket":"C.P.L.A. No. 579-K of 2021","subject":"constitutional","holding":"Cross-examination is the highest and most indispensable test for discovery of truth and a vested right, a fundamental limb of natural justice. Denying the petitioner any opportunity to cross-examine 138 witnesses violated Article 10-A's fair-trial guarantee; it is not a minor procedural flaw but a serious error undermining the misconduct case. The Tribunal judgment was set aside and the matter remanded for a de-novo inquiry.","verified":"2026-09-24","caption":"138 gawahon se jirh ka moqa diye baghair inquiry kya fair trial hai?\nSupreme Court ne 2026 SCMR 692 mein faisla diya ke cross-examination sach tak pohanchnay ka sab se ahm zariya hai aur is se mehroom karna Article 10-A (fair trial) ki khilaf warzi hai. Yeh mamuli ghalti nahi, sanjeeda khami hai. Case dobara inquiry ke liye bheja gaya.\nCase: Muhammad Ali Wassan vs Prime Minister of Pakistan, 2026 SCMR 692. Supreme Court of Pakistan, decided 4 June 2025. Bench: Muhammad Shafi Siddiqui and Salahuddin Panhwar, JJ.\nApne case ke mutaliq mashwara ke liye rabta karein: 0311-2610683.\nKya inquiry mein mulzim ka dafaa ka haq waqai mehfooz rehta hai?\n#ConstitutionalLaw #FairTrial #SupremeCourtOfPakistan #PakistanLaw #TaqiKazmi","card":"assets/legal-hub/cards/2026-scmr-692.png","reference":"2026 SCMR 692"}];
    const HUB_AMENDMENTS=[{"num":1,"title":"Prevention of Electronic Crimes (Amendment) Act, 2025 (Act No. II of 2025)","what_changed":"A new Section 26A punishes intentionally spreading false or fake information online (likely to cause fear, panic or disorder) with up to 3 years imprisonment and/or a fine up to Rs 2 million. The Act creates a Social Media Protection Authority (to regulate/enlist social media platforms and act on complaints), Social Media Protection Tribunals, and a new National Cyber Crime Investigation Agency (NCCIA) replacing the FIA's Cyber Crime Wing.\n- **Why it matters:** Every social media user, journalist, and vlogger in Pakistan now faces criminal liability for \"fake news,\" and platforms can be ordered to remove content. It is the most consequential digital-speech law since PECA 2016.\n- **Date:** Presidential assent 29 January 2025; in force at once.\n- **Source:** Gazette of Pakistan (Extraordinary), 29 Jan 2025 (copy hosted by HRCP): https://hrcp-web.org/hrcpweb/wp-content/uploads/2020/09/2025-LWC10-PECA-Amendment-Act-2025.pdf","why_matters":"Every social media user, journalist, and vlogger in Pakistan now faces criminal liability for \"fake news,\" and platforms can be ordered to remove content. It is the most consequential digital-speech law since PECA 2016.\n- **Date:** Presidential assent 29 January 2025; in force at once.\n- **Source:** Gazette of Pakistan (Extraordinary), 29 Jan 2025 (copy hosted by HRCP): https://hrcp-web.org/hrcpweb/wp-content/uploads/2020/09/2025-LWC10-PECA-Amendment-Act-2025.pdf","date":"Presidential assent 29 January 2025; in force at once.","sources":["https://hrcp-web.org/hrcpweb/wp-content/uploads/2020/09/2025-LWC10-PECA-Amendment-Act-2025.pdf"]},{"num":2,"title":"Digital Nation Pakistan Act, 2025","what_changed":"Creates three bodies: a National Digital Commission (chaired by the Prime Minister, with all Chief Ministers), a Pakistan Digital Authority (to draft and implement a National Digital Masterplan), and an Oversight Committee. The stated goal is a \"digital nation\": digital society, digital economy and digital governance, including mobile access to government services and documents.\n- **Why it matters:** This is the legal backbone for digitising NADRA-linked services, land records and government payments. For citizens it promises fewer office visits; for businesses it promises easier compliance and ease of doing business.\n- **Date:** Approved by both Houses; in force 29 January 2025.\n- **Sources:** https://moitt.gov.pk/SliderDetail/YjY0ZGZiOTctNjY2Yy00YWQwLTg3ZmEtZDUyMGYxNjlkOTM0 and http://pid.gov.pk/site/press_detail/27860","why_matters":"This is the legal backbone for digitising NADRA-linked services, land records and government payments. For citizens it promises fewer office visits; for businesses it promises easier compliance and ease of doing business.\n- **Date:** Approved by both Houses; in force 29 January 2025.\n- **Sources:** https://moitt.gov.pk/SliderDetail/YjY0ZGZiOTctNjY2Yy00YWQwLTg3ZmEtZDUyMGYxNjlkOTM0 and http://pid.gov.pk/site/press_detail/27860","date":"Approved by both Houses; in force 29 January 2025.","sources":["http://pid.gov.pk/site/press_detail/27860","https://moitt.gov.pk/SliderDetail/YjY0ZGZiOTctNjY2Yy00YWQwLTg3ZmEtZDUyMGYxNjlkOTM0"]},{"num":3,"title":"Islamabad Capital Territory Child Marriage Restraint Act, 2025 (Act No. XI of 2025)","what_changed":"Sets 18 years as the minimum marriage age for both boys and girls in Islamabad. Nikah registrars must verify both parties' CNICs; a registrar who solemnises an underage marriage faces up to 1 year in jail and Rs 100,000 fine. An adult man marrying a child faces up to 3 years rigorous imprisonment; living with a child in a marital relationship is treated as statutory rape; parents/guardians who facilitate face 2-3 years.\n- **Why it matters:** Pakistan has about 19 million child brides. This is the first federal law fixing 18 for both sexes, and it is being cited as the model for the provinces.\n- **Date:** Passed by National Assembly 16 May 2025, Senate 19 May 2025; presidential assent 29 May 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","why_matters":"Pakistan has about 19 million child brides. This is the first federal law fixing 18 for both sexes, and it is being cited as the model for the provinces.\n- **Date:** Passed by National Assembly 16 May 2025, Senate 19 May 2025; presidential assent 29 May 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","date":"Passed by National Assembly 16 May 2025, Senate 19 May 2025; presidential assent 29 May 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214"]},{"num":4,"title":"Finance Act, 2025 (Act No. XIX of 2025)","what_changed":"Annual budget law amending the Income Tax Ordinance 2001, Sales Tax Act 1990 and other fiscal laws. Notable changes: revised salaried tax slabs (basic exemption Rs 600,000 retained, higher rates in middle/upper slabs); pension and annuity from a former employer became taxable (at a reduced rate) from 1 July 2025; 50% of business expenditure disallowed where sales over Rs 200,000 are received in cash; 10% disallowance on purchases from non-NTN holders; withholding tax on cash withdrawals by non-ATL persons raised from 0.6% to 0.8%; new \"eligible vs ineligible persons\" regime (Section 114C); FBR arrest powers in tax fraud cases above Rs 50 million require a 3-member committee's approval and magistrate production within 24 hours; Climate Support Levy of Rs 2.50/litre on petroleum products.\n- **Why it matters:** Directly affects every salaried person's payslip, every business's deductible expenses, and fuel prices. Non-filers face higher withholding on banking, property and vehicle transactions.\n- **Date:** Passed 26 June 2025 (na.gov.pk lists 27 June 2025); effective 1 July 2025.\n- **Sources:** https://na.gov.pk/en/acts-tenure.php/content.php?id=214 ; analysis: https://www.pwc.com.pk/en/tax-memorandum/AFFs%20Tax%20Memorandum%20on%20changes%20in%20Finance%20Bill%202025.pdf","why_matters":"Directly affects every salaried person's payslip, every business's deductible expenses, and fuel prices. Non-filers face higher withholding on banking, property and vehicle transactions.\n- **Date:** Passed 26 June 2025 (na.gov.pk lists 27 June 2025); effective 1 July 2025.\n- **Sources:** https://na.gov.pk/en/acts-tenure.php/content.php?id=214 ; analysis: https://www.pwc.com.pk/en/tax-memorandum/AFFs%20Tax%20Memorandum%20on%20changes%20in%20Finance%20Bill%202025.pdf","date":"Passed 26 June 2025 (na.gov.pk lists 27 June 2025); effective 1 July 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214","https://www.pwc.com.pk/en/tax-memorandum/AFFs%20Tax%20Memorandum%20on%20changes%20in%20Finance%20Bill%202025.pdf"]},{"num":5,"title":"Civil Servants (Amendment) Act, 2025 (Act No. XX of 2025)","what_changed":"Amends the Civil Servants Act, 1973, which governs appointment, promotion, discipline and retirement of federal civil servants. (Detailed section-wise changes as per the official Gazette.)\n- **Why it matters:** Governs the careers of hundreds of thousands of federal government employees, including service structure and disciplinary rules.\n- **Date:** 27 June 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","why_matters":"Governs the careers of hundreds of thousands of federal government employees, including service structure and disciplinary rules.\n- **Date:** 27 June 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","date":"27 June 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214"]},{"num":6,"title":"Anti-terrorism (Amendment) Act, 2025","what_changed":"Reinserts Section 11EEEE into the Anti-Terrorism Act, 1997: the federal government, or the armed forces/civil armed forces (where Section 4 is invoked), may order preventive detention of a terrorism suspect for up to 90 days after recording reasons, for inquiry by a Joint Investigation Team (police, intelligence agencies, armed forces). It carries a 3-year sunset clause. Safeguards: detentions beyond 3 months must comply with Article 10 of the Constitution (grounds communicated, counsel, magistrate within 24 hours).\n- **Why it matters:** A person can be held for three months without charge on suspicion of terrorism-related activity, including target killing, kidnapping for ransom or extortion. Civil liberties groups (including UN Special Procedures) raised due-process concerns; the government says judicial oversight prevents misuse.\n- **Date:** Passed by National Assembly 13 August 2025 and Senate 19 August 2025; presidential assent 31 August 2025.\n- **Sources:** https://spcommreports.ohchr.org/TMResultsBase/DownLoadPublicCommunicationFile?gId=30492 ; https://www.pakistantoday.com.pk/2025/08/31/president-zardari-signs-anti-terrorism-amendment-bill-2025-into-law","why_matters":"A person can be held for three months without charge on suspicion of terrorism-related activity, including target killing, kidnapping for ransom or extortion. Civil liberties groups (including UN Special Procedures) raised due-process concerns; the government says judicial oversight prevents misuse.\n- **Date:** Passed by National Assembly 13 August 2025 and Senate 19 August 2025; presidential assent 31 August 2025.\n- **Sources:** https://spcommreports.ohchr.org/TMResultsBase/DownLoadPublicCommunicationFile?gId=30492 ; https://www.pakistantoday.com.pk/2025/08/31/president-zardari-signs-anti-terrorism-amendment-bill-2025-into-law","date":"Passed by National Assembly 13 August 2025 and Senate 19 August 2025; presidential assent 31 August 2025.","sources":["https://spcommreports.ohchr.org/TMResultsBase/DownLoadPublicCommunicationFile?gId=30492","https://www.pakistantoday.com.pk/2025/08/31/president-zardari-signs-anti-terrorism-amendment-bill-2025-into-law"]},{"num":11,"title":"Supreme Court (Practice and Procedure) (Amendment) Act, 2025 (Act No. XXXVI of 2025)","what_changed":"Amends the Supreme Court (Practice and Procedure) Act, 2023, aligning the Supreme Court's internal procedures (benches, case allocation) with the 27th Constitutional Amendment, which created the Federal Constitutional Court and redistributed jurisdiction.\n- **Why it matters:** Determines how the country's top court organises benches and takes up cases, including suo motu matters that affect the public.\n- **Date:** 15 November 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","why_matters":"Determines how the country's top court organises benches and takes up cases, including suo motu matters that affect the public.\n- **Date:** 15 November 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","date":"15 November 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214"]},{"num":12,"title":"Constitution (Twenty-Seventh Amendment) Act, 2025 (Act No. XXXII of 2025)","what_changed":"Creates a new Federal Constitutional Court; amends Article 243 (armed forces command: Chief of Army Staff becomes Chief of Defence Forces; the post of Chairman Joint Chiefs of Staff Committee abolished from 27 November 2025); lifetime rank, privileges and status for Field Marshal/equivalent ranks; changes to judicial appointment and transfer processes; insertion of \"Federal Constitutional Court\" in Article 6 (high treason clause). Amends Articles 10, 17, 42, 105, 146, 152, 159, 168, 175, 176, 214, 239, 243 and 255.\n- **Why it matters:** The most far-reaching constitutional change since the 18th Amendment: it reshapes the judiciary, the military command structure and federal-provincial fiscal relations (NFC Award review). Every citizen is affected by who interprets the Constitution and who commands the armed forces.\n- **Date:** Passed by Senate 13 November 2025 (64 votes); presidential assent 13 November 2025.\n- **Sources:** https://www.radio.gov.pk/13-11-2025/senate-passes-the-constitution-twenty-seventh-amendment-bill-2025 ; https://na.gov.pk/en/acts-tenure.php/content.php?id=214","why_matters":"The most far-reaching constitutional change since the 18th Amendment: it reshapes the judiciary, the military command structure and federal-provincial fiscal relations (NFC Award review). Every citizen is affected by who interprets the Constitution and who commands the armed forces.\n- **Date:** Passed by Senate 13 November 2025 (64 votes); presidential assent 13 November 2025.\n- **Sources:** https://www.radio.gov.pk/13-11-2025/senate-passes-the-constitution-twenty-seventh-amendment-bill-2025 ; https://na.gov.pk/en/acts-tenure.php/content.php?id=214","date":"Passed by Senate 13 November 2025 (64 votes); presidential assent 13 November 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214","https://www.radio.gov.pk/13-11-2025/senate-passes-the-constitution-twenty-seventh-amendment-bill-2025"]},{"num":13,"title":"Off the Grid (Captive Power Plants) Levy Act, 2025 (Act No. XIV of 2025)","what_changed":"Imposes a levy on captive power plants (industrial units generating their own electricity off the national grid), as part of the government's plan to shift industry onto the grid.\n- **Why it matters:** Raises power costs for industry, which feeds into the prices of manufactured goods ordinary consumers buy.\n- **Date:** 30 May 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","why_matters":"Raises power costs for industry, which feeds into the prices of manufactured goods ordinary consumers buy.\n- **Date:** 30 May 2025.\n- **Source:** National Assembly official Acts list: https://na.gov.pk/en/acts-tenure.php/content.php?id=214","date":"30 May 2025.","sources":["https://na.gov.pk/en/acts-tenure.php/content.php?id=214"]}];
    let citations=[],amendments=[],citationPage=1,amendmentVisible=8;const citationsPerPage=6;
    const citationGrid=document.getElementById('citation-grid'),citationSearch=document.getElementById('citation-search'),citationCourt=document.getElementById('citation-court'),citationYear=document.getElementById('citation-year'),citationSubject=document.getElementById('citation-subject'),citationEmpty=document.getElementById('citation-empty'),citationPrev=document.getElementById('citation-prev'),citationNext=document.getElementById('citation-next'),citationPageStatus=document.getElementById('citation-page-status'),citationDialog=document.getElementById('citation-dialog');
    const amendmentsGrid=document.getElementById('amendments-grid'),amendmentSearch=document.getElementById('amendment-search'),amendmentYear=document.getElementById('amendment-year'),amendmentEmpty=document.getElementById('amendment-empty'),amendmentMore=document.getElementById('amendment-more');
    const titleCase=s=>String(s||'').replace(/\b\w/g,c=>c.toUpperCase());
    const sourceFromCaption=caption=>{const matches=String(caption||'').match(/https?:\/\/[^\s]+/g)||[];return matches.length?matches[0].replace(/[.,;]+$/,''):''};
    const subjectImages=Object.freeze({
      criminal:'assets/legal-hub/subjects/criminal.webp',
      family:'assets/legal-hub/subjects/family.webp',
      civil:'assets/legal-hub/subjects/civil.webp',
      service:'assets/legal-hub/subjects/service.webp',
      constitutional:'assets/legal-hub/subjects/constitutional.webp',
      tax:'assets/legal-hub/subjects/tax.webp',
      cyber:'assets/legal-hub/subjects/cyber.webp',
      courts:'assets/legal-hub/subjects/courts.webp',
      general:'assets/legal-hub/subjects/general.webp'
    });
    const subjectDescriptions=Object.freeze({criminal:'Scales of justice representing criminal law',family:'Hands protecting a family home, representing family law',civil:'Legal books and a courthouse representing civil law',service:'A professional briefcase representing service and employment law',constitutional:'A grand court building representing constitutional law',tax:'A calculator and coins representing tax and finance law',cyber:'A secure padlock on a digital network representing cyber law',courts:'Court columns and law books representing court procedure',general:'Scales of justice representing legal research'});
    const normalizeSubject=subject=>{const value=String(subject||'').trim().toLowerCase();return Object.prototype.hasOwnProperty.call(subjectImages,value)?value:'general'};
    const subjectImageFor=subject=>subjectImages[normalizeSubject(subject)];
    const subjectAltFor=subject=>subjectDescriptions[normalizeSubject(subject)];
    function amendmentSubject(title){const value=String(title||'').toLowerCase();if(/cyber|digital|peca|electronic crimes?/.test(value))return'cyber';if(/finance|tax|levy/.test(value))return'tax';if(/terrorism|criminal|narcotics?|prosecution/.test(value))return'criminal';if(/child[-\s]+marriage|family|domestic workers/.test(value))return'family';if(/courts?|procedure|evidence|shahadat|legal practitioners?|bar councils?/.test(value))return'courts';if(/constitution/.test(value))return'constitutional';if(/civil servants?|employment/.test(value))return'service';if(/citizenship|naturalization|business|karobar|property|succession/.test(value))return'civil';return'general'}
    function groupSubject(items){const counts=new Map();items.forEach(item=>{const subject=normalizeSubject(item.subject);if(subject!=='general')counts.set(subject,(counts.get(subject)||0)+1)});return[...counts].sort((a,b)=>b[1]-a[1])[0]?.[0]||'general'}
    function fillSelect(select,values,label){values.sort().forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=`${label}: ${titleCase(value)}`;select.append(option)})}
    function citationMatches(c){const q=citationSearch.value.trim().toLowerCase(),year=String(c.citation||c.date||'').match(/\b(20\d{2})\b/)?.[1]||'';return(citationCourt.value==='all'||c.court===citationCourt.value)&&(citationYear.value==='all'||year===citationYear.value)&&(citationSubject.value==='all'||c.subject===citationSubject.value)&&(`${c.citation} ${c.title} ${c.court} ${c.date} ${c.bench} ${c.docket} ${c.subject} ${c.holding}`.toLowerCase().includes(q))}
    function renderCitations(){const list=citations.filter(citationMatches),pages=Math.max(1,Math.ceil(list.length/citationsPerPage));citationPage=Math.min(citationPage,pages);const start=(citationPage-1)*citationsPerPage,shown=list.slice(start,start+citationsPerPage);citationGrid.innerHTML=shown.map(c=>{const ref=c.src||sourceFromCaption(c.caption),verifiedSrc=Boolean(c.src),subject=normalizeSubject(c.subject),card=/^assets\/legal-hub\/cards\/.+\.png$/.test(String(c.card||''))?c.card:'';return `<article class="citation-card"><div class="citation-card-media${card?' card-art':''}"><img src="${esc(card||subjectImageFor(subject))}" loading="lazy" decoding="async" alt="${esc(card?`Judgment card for ${c.citation}: ${c.title}`:subjectAltFor(subject))}">${card?'':`<span class="subject-chip">${esc(titleCase(subject))}</span>`}</div><div class="citation-card-copy"><span class="citation-code">${esc(c.citation)}</span><h4>${esc(c.title)}</h4><dl class="citation-facts"><div><dt>Court</dt><dd>${esc(c.court)}</dd></div><div><dt>Decision</dt><dd>${esc(c.date)}</dd></div><div><dt>Bench</dt><dd>${esc(c.bench)}</dd></div><div><dt>Docket</dt><dd>${esc(c.docket)}</dd></div><div><dt>Subject</dt><dd>${esc(titleCase(c.subject))}</dd></div></dl><p class="holding">${esc(c.holding)}</p><div class="reference-line"><strong>${ref?(verifiedSrc?'Verified primary source':'Supporting link'):'Citation status'}:</strong> ${ref?`<a href="${esc(ref)}" target="_blank" rel="noopener noreferrer">${esc(new URL(ref).hostname)} ↗</a>`:`${esc(c.reference||c.citation)} · ${esc(c.court)} · Primary-source document not publicly linked here`}</div><button class="caption-open" type="button" data-citation-index="${citations.indexOf(c)}">Read full case post & caption</button></div></article>`}).join('');citationEmpty.style.display=list.length?'none':'block';document.getElementById('citation-pagination').style.display=list.length?'flex':'none';citationPrev.disabled=citationPage<=1;citationNext.disabled=citationPage>=pages;citationPageStatus.textContent=`Page ${citationPage} of ${pages}`}
    function openCitation(index){const c=citations[index];if(!c)return;const ref=c.src||sourceFromCaption(c.caption),verifiedSrc=Boolean(c.src),subject=normalizeSubject(c.subject),card=/^assets\/legal-hub\/cards\/.+\.png$/.test(String(c.card||''))?c.card:'';document.getElementById('citation-dialog-title').textContent=`${c.citation} | ${c.title}`;const body=document.getElementById('citation-dialog-body');body.innerHTML=`<div class="citation-dialog-image${card?' card-art':''}"><img src="${esc(card||subjectImageFor(subject))}" alt="${esc(card?`Judgment card for ${c.citation}: ${c.title}`:subjectAltFor(subject))}">${card?'':`<span class="subject-chip">${esc(titleCase(subject))}</span>`}</div><dl class="citation-detail-list"><div><dt>Court</dt><dd>${esc(c.court)}</dd></div><div><dt>Date of decision</dt><dd>${esc(c.date)}</dd></div><div><dt>Bench</dt><dd>${esc(c.bench)}</dd></div><div><dt>Docket number</dt><dd>${esc(c.docket)}</dd></div><div><dt>Subject area</dt><dd>${esc(titleCase(c.subject))}</dd></div><div><dt>Citation</dt><dd>${esc(c.citation)}</dd></div></dl><h3>Holding / ratio</h3><p>${esc(c.holding)}</p><h3>Professional post caption</h3>`;const caption=document.createElement('p');caption.className='citation-caption';caption.append(linkifyText(c.caption));body.append(caption);const refs=document.createElement('div');refs.className='source-list';const heading=document.createElement('h3');heading.textContent=ref?(verifiedSrc?'Verified primary source':'Supporting reference'):'Citation status';refs.append(heading);if(ref){const link=document.createElement('a');link.href=ref;link.target='_blank';link.rel='noopener noreferrer';link.textContent=`Open ${verifiedSrc?'primary source':'supporting link'}: ${new URL(ref).hostname} ↗`;refs.append(link)}else{const citationRef=document.createElement('p');citationRef.textContent=`${c.reference||c.citation} · ${c.court}. Primary-source document is not publicly linked in this record.`;refs.append(citationRef)}body.append(refs);openDialog(citationDialog)}
    citationGrid.addEventListener('click',e=>{const button=e.target.closest('[data-citation-index]');if(button)openCitation(Number(button.dataset.citationIndex))});
    [citationSearch,citationCourt,citationYear,citationSubject].forEach(control=>control.addEventListener(control===citationSearch?'input':'change',()=>{citationPage=1;renderCitations()}));citationPrev.addEventListener('click',()=>{if(citationPage>1){citationPage--;renderCitations();document.getElementById('judgment-citations').scrollIntoView({behavior:'smooth'})}});citationNext.addEventListener('click',()=>{citationPage++;renderCitations();document.getElementById('judgment-citations').scrollIntoView({behavior:'smooth'})});
    const cleanSeedText=(text,marker)=>String(text||'').split(marker)[0].trim();
    const pdfSource=url=>/\.pdf(?:$|\?)/i.test(url);
    function amendmentMatches(a){const q=amendmentSearch.value.trim().toLowerCase(),hay=`${a.title} ${a.what_changed} ${a.why_matters} ${a.date}`.toLowerCase();return(amendmentYear.value==='all'||hay.includes(amendmentYear.value))&&hay.includes(q)}
    const legislationType=title=>/resolution/i.test(title)?'ASSEMBLY RESOLUTION':/bill/i.test(title)?'BILL / PASSAGE RECORD':/act|ordinance|amendment/i.test(title)?'ENACTED LAW':'POLICY RECORD';
    function renderAmendments(){const list=amendments.filter(amendmentMatches),shown=list.slice(0,amendmentVisible);amendmentsGrid.innerHTML=shown.map((a,index)=>{const what=cleanSeedText(a.what_changed,'\n- **Why it matters:**'),why=cleanSeedText(a.why_matters,'\n- **Date:**'),subject=amendmentSubject(a.title);return `<article class="amendment-card"><div class="amendment-card-media"><div class="record-visual subject-${esc(subject)}" role="img" aria-label="Editorial panel for ${esc(a.title)}"><strong>${esc(a.title)}</strong><small>${esc(titleCase(subject))} · ${String(index+1).padStart(2,'0')}</small></div></div><div class="amendment-card-copy"><span class="record-number">${esc(legislationType(a.title))} · RECORD ${String(index+1).padStart(2,'0')}</span><h4>${esc(a.title)}</h4>${a.date?`<p class="amendment-date">${esc(a.date)}</p>`:''}${what?`<h5>What changed</h5><p>${esc(what)}</p>`:''}${why?`<h5>Why it matters</h5><p>${esc(why)}</p>`:`<p class="amendment-date">Source linked; provision-level summary pending review.</p>`}${(a.sources||[]).length?`<div class="amendment-links">${a.sources.map((url,i)=>`<a class="official-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${pdfSource(url)?'Source PDF':`${sourceAuthority(url)||`Source ${i+1}`}`} ↗</a>`).join('')}</div>`:''}</div></article>`}).join('');amendmentEmpty.style.display=list.length?'none':'block';amendmentMore.style.display=list.length>amendmentVisible?'inline-block':'none'}
    [amendmentSearch,amendmentYear].forEach(control=>control.addEventListener(control===amendmentSearch?'input':'change',()=>{amendmentVisible=8;renderAmendments()}));amendmentMore.addEventListener('click',()=>{amendmentVisible+=8;renderAmendments()});
    function sourceAuthority(url){const host=new URL(url).hostname.replace(/^www\./,'');const labels={'na.gov.pk':'National Assembly of Pakistan','moitt.gov.pk':'Ministry of IT & Telecommunication','pid.gov.pk':'Press Information Department','pas.gov.pk':'Provincial Assembly of Sindh','sindhlaws.gov.pk':'Sindh Laws','radio.gov.pk':'Radio Pakistan','spcommreports.ohchr.org':'UN Special Procedures'};return labels[host]||''}
